let activeTab="all",search="",category="",warehouse="",selected=new Set(),toastTimer,activeWorkshop=appSettings.defaultWorkshop,workshopSearch="",activeVehicle="Coche 100",vehicleSearch="";
function stockAt(p,location){return Number(p.workshopStock?.[location])||0}
function totalStock(p){return WORKSHOPS.reduce((sum,w)=>sum+stockAt(p,w),0)}
