function workshopStatus(p,count){return count===0?["Sin stock","out"]:count<=p.min?["Stock bajo","low"]:["En nivel",""]}
function filtered(){return products.filter(p=>(!search||[p.name,p.sku,p.barcode||"",p.category].some(v=>v.toLowerCase().includes(search.toLowerCase())))&&(!category||p.category===category)&&(!warehouse||stockAt(p,warehouse)>0)&&(activeTab==="all"||activeTab==="low"&&totalStock(p)>0&&totalStock(p)<=p.min||activeTab==="out"&&totalStock(p)===0))}
function updateCounts(){const low=products.filter(p=>totalStock(p)>0&&totalStock(p)<=p.min).length,out=products.filter(p=>totalStock(p)===0).length,units=products.reduce((a,p)=>a+totalStock(p),0);$("#active-count").textContent=products.length+" repuestos activos";$("#units-count").textContent=units.toLocaleString("es-UY");$("#low-count").textContent=low;$("#nav-count").textContent=products.length.toLocaleString("es-UY");$("#tab-all-count").textContent=products.length;$("#tab-low-count").textContent="· "+low;$("#tab-out-count").textContent="· "+out;const cat=$("#category-filter"),previous=category;cat.innerHTML='<option value="">Categoría: todas</option>'+[...new Set([...CATEGORIES,...products.map(p=>p.category)])].sort((a,b)=>a.localeCompare(b,"es")).map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join("");cat.value=previous}
