function scanProductCode(announce=false){const code=$("#barcode-scan").value.trim(),product=findProductCode(code),feedback=$("#scan-feedback");if(product){$("#product-select").value=String(product.id);feedback.textContent="Repuesto encontrado: "+product.name+" · ingresa la cantidad.";feedback.className="scan-feedback found";if(announce){$("#movement-form [name=quantity]").focus();logActivity("Código escaneado",code+" · "+product.name)}return true}$("#product-select").value="";if(code){feedback.textContent="No encontramos ese código. Verifica el código o registra el repuesto.";feedback.className="scan-feedback missing"}else{feedback.textContent="El lector funciona como teclado. También puedes escribir el SKU.";feedback.className="scan-feedback"}return false}
