function applyRolePermissions(){const admin=isAdmin(),write=canWrite();$("#settings-admin-only").hidden=!admin;$("#settings-form [name=company]").disabled=!admin;$("#settings-form [name=area]").disabled=!admin;$("#settings-form [name=defaultWorkshop]").disabled=!admin;$("#settings-form [name=defaultMinimum]").disabled=!admin;$("#settings-form button[type=submit]").hidden=!admin;["#new-product-btn","#add-btn","#movement-add-btn","#workshop-entry-btn","#workshop-transfer-btn","#vehicle-assign-btn","#dashboard-movement-btn"].forEach(s=>{const el=$(s);if(el)el.hidden=!write});const adjustment=$("#movement-form [name=type] option[value=ajuste]"),transfer=$("#movement-form [name=type] option[value=traslado]");if(adjustment)adjustment.disabled=isOperator();if(transfer)transfer.disabled=isOperator();if(isOperator()&&["ajuste","traslado"].includes($("#movement-form [name=type]").value))$("#movement-form [name=type]").value="entrada";$("#user-modal-backdrop").hidden=true}
