function reportMovements(){const from=$("#report-date-from").value,to=$("#report-date-to").value,workshop=$("#report-workshop").value;if(from&&to&&from>to){notify("La fecha inicial debe ser anterior a la fecha final.");return []}const start=from?new Date(from+"T00:00:00").getTime():-Infinity,end=to?new Date(to+"T23:59:59.999").getTime():Infinity;return movements.filter(m=>{const time=new Date(m.date).getTime();return time>=start&&time<=end&&(!workshop||m.warehouse===workshop||m.destination===workshop)}).sort((a,b)=>new Date(b.date)-new Date(a.date))}
