function getMovementExportData(){const type=$("#movement-type-filter").value,store=$("#movement-warehouse-filter").value,q=$("#movement-search").value.trim().toLowerCase(),cutoff=Date.now()-30*86400000,list=movements.filter(m=>{const p=products.find(x=>x.id===m.productId)||{};return new Date(m.date).getTime()>=cutoff&&(!type||m.type===type)&&(!store||m.warehouse===store||m.destination===store)&&(!q||[m.id,m.reference,p.name,p.sku,m.note,m.destination,m.vehicleId].some(v=>String(v||"").toLowerCase().includes(q)))});return list.map(m=>{const p=products.find(x=>x.id===m.productId)||{};return[m.id,new Date(m.date).toLocaleString("es-UY"),m.type,p.name||"",p.sku||"",m.warehouse,m.destination||"—",m.vehicleId||"—",Number(m.delta)||0,Number(m.toStock)||0,m.reference||"",m.user||"Lucía Martínez"]})}
function performExport(kind){const inventory=kind.startsWith("inventory"),reports=kind.startsWith("reports"),pdf=kind.endsWith("pdf"),today=new Date().toISOString().slice(0,10),columns=inventory?inventoryExportColumns:reports?reportColumns:movementExportColumns,data=inventory?filtered().map(p=>[p.name,p.sku,p.barcode||"",p.category,stockAt(p,"Bella Unión"),stockAt(p,"Montevideo"),totalStock(p),p.min,p.cost,status(p)[0]]):reports?reportMovementRows(reportMovements()):getMovementExportData(),title=inventory?"Inventario de repuestos":reports?"Informe de movimientos · "+$("#report-date-from").value+" a "+$("#report-date-to").value:"Movimientos de stock",filename=(inventory?"inventario-repuestos":reports?"informe-operativo":"movimientos-stock")+"-"+today+(pdf?".pdf":".xlsx");logActivity("Exportación",filename);if(pdf)exportPdf(filename,title,columns,data);else exportXlsx(filename,title,columns,data).then(()=>notify("Archivo XLSX descargado.")).catch(()=>notify("No se pudo generar el archivo XLSX."))}
